def match_parens(lst):
    def analyze(s):
        balance = 0
        min_prefix = 0
        for ch in s:
            if ch == '(':
                balance += 1
            else:
                balance -= 1
            min_prefix = min(min_prefix, balance)
        return balance, min_prefix

    b1, m1 = analyze(lst[0])
    b2, m2 = analyze(lst[1])

    if b1 + b2 != 0:
        return 'No'

    if b1 + m2 >= 0 and b2 + m1 >= 0:
        return 'Yes'
    return 'No'
